"""Loader for the AIDA intCars.rda dataset (S4 intData object).

The AIDA package ships ``data/intCars.rda`` containing:
  * ``microdata``: 27 x 9 data.frame with LB_/UB_ columns for Price, EngCap,
    Top Speed and Acceleration plus a ``class`` factor.
  * ``intData``: an S4 ``intData`` object (MAINT.Data style) already holding the
    interval Centers/Ranges on the lnPrice scale, the latent-parameter setup
    (``U_id_symmetric`` with delta = E(U^2)/4 = 1/12) and the car labels.

``pyreadr`` cannot convert the S4 object, so we use the pure-python ``rdata``
package and walk the returned namespace.
"""

from __future__ import annotations

import os
from dataclasses import dataclass

import numpy as np

# REPRO_DATA_CACHE is the shared raw-data cache; fall back to the repo copy.
CACHE = os.environ.get("REPRO_DATA_CACHE", "")


def _candidates():
    name = "intCars.rda"
    out = []
    if CACHE:
        out.append(os.path.join(CACHE, "AIDA", "data", name))
        out.append(os.path.join(CACHE, name))
    out.append(os.path.join("repo", "data", name))
    out.append(os.path.join("third_party", "AIDA", "data", name))
    return out


@dataclass
class CarsData:
    centers: np.ndarray          # (n, p) interval centers c = (a+b)/2
    ranges: np.ndarray           # (n, p) interval ranges r = b - a
    lower: np.ndarray            # (n, p) interval lower bounds
    upper: np.ndarray            # (n, p) interval upper bounds
    labels: list                 # n car-model labels
    var_names: list              # p variable names
    micro_lower: np.ndarray      # (n, p) raw (non-logged) lower bounds
    micro_upper: np.ndarray      # (n, p) raw (non-logged) upper bounds
    micro_vars: list
    latent_case: str
    delta: float                 # E(U^2)/4 for U ~ Uniform[-1,1]

    @property
    def n(self):
        return self.centers.shape[0]

    @property
    def p(self):
        return self.centers.shape[1]


def _unwrap(obj):
    """Recursively pull numpy arrays / lists out of rdata's wrapper objects."""
    # rdata returns converted objects; S4 objects arrive as dict-like
    # 'namespace' objects with attribute ``.s4slots`` or as plain dicts.
    for attr in ("s4slots", "_s4slots", "slots"):
        if hasattr(obj, attr):
            return getattr(obj, attr)
    if isinstance(obj, dict):
        return obj
    if hasattr(obj, "__dict__") and obj.__dict__:
        return obj.__dict__
    return obj


def _find_key(container, *keys, depth=0, max_depth=4):
    """Depth-first search for any of the given keys in nested containers."""
    if depth > max_depth:
        return None
    if isinstance(container, dict):
        for k, v in container.items():
            ks = str(k)
            for want in keys:
                if ks == want or ks.endswith(want):
                    return v
        for v in container.values():
            got = _find_key(v, *keys, depth=depth + 1, max_depth=max_depth)
            if got is not None:
                return got
    return None


def _as_matrix(x):
    """Convert an rdata matrix object (dict with 'data' or array) to ndarray."""
    arr = x
    if isinstance(arr, dict):
        for k in ("data", "values", "value"):
            if k in arr:
                arr = arr[k]
                break
    if hasattr(arr, "data"):
        arr = arr.data
    if isinstance(arr, list):
        arr = np.array(arr, dtype=float)
    arr = np.asarray(arr)
    if arr.dtype == object:
        arr = arr.astype(float)
    return arr


def _as_str_list(x):
    if isinstance(x, dict):
        for k in ("data", "values", "value"):
            if k in x:
                x = x[k]
                break
    if hasattr(x, "data"):
        x = x.data
    arr = np.asarray(x)
    return [str(v) for v in arr.ravel()]


def load_intCars(path=None):
    """Load the intCars dataset; returns a CarsData object."""
    import rdata

    if path is None:
        path = next((p for p in _candidates() if os.path.exists(p)), None)
        if path is None:
            raise FileNotFoundError(
                "intCars.rda not found; looked in " + repr(_candidates())
            )

    conv = rdata.read_rda(path)
    obj = conv["intCars"]

    # ---- S4 intData object -------------------------------------------
    d = _unwrap(obj)
    intd = None
    if isinstance(d, dict):
        for k, v in d.items():
            if str(k) == "intData" or str(k).endswith("intData"):
                intd = v
                break
    if intd is None:
        intd = _find_key(d, "intData")
    slots = _unwrap(intd)

    centers = _as_matrix(_find_key(slots, "Centers"))
    ranges = _as_matrix(_find_key(slots, "Ranges"))
    lower = _as_matrix(_find_key(slots, "LowerBounds"))
    upper = _as_matrix(_find_key(slots, "UpperBounds"))
    labels = _as_str_list(_find_key(slots, "ObsNames"))
    var_names = _as_str_list(_find_key(slots, "VarNames"))
    latent_case = str(_find_key(slots, "LatentCase"))
    lp = _find_key(slots, "LatentParam")
    delta = float(np.asarray(_as_matrix(lp)).ravel()[0])

    # ---- raw microdata (for the lnPrice verification, R2) ------------
    micro = d.get("microdata") if isinstance(d, dict) else None
    micro_lower = micro_upper = None
    micro_vars = []
    if micro is not None:
        md = _unwrap(micro)
        cols = {}
        for k, v in (md.items() if isinstance(md, dict) else []):
            cols[str(k)] = np.asarray(_as_matrix(v)).ravel()
        micro_vars = list(cols)
        lb_cols = [c for c in micro_vars if c.startswith("LB_")]
        ub_cols = [c for c in micro_vars if c.startswith("UB_")]
        if lb_cols:
            micro_lower = np.column_stack([cols[c] for c in lb_cols])
            micro_upper = np.column_stack([cols[c] for c in ub_cols])
            micro_vars = [c[3:] for c in lb_cols]

    return CarsData(
        centers=centers, ranges=ranges, lower=lower, upper=upper,
        labels=labels, var_names=var_names,
        micro_lower=micro_lower, micro_

